import bpy
bpy.ops.object.select_all(action='DESELECT')
names = [o.name for o in bpy.data.objects if o.type in ('CURVE','FONT')]
converted = []
for name in names:
    o = bpy.data.objects.get(name)
    if o is None: continue
    try:
        bpy.context.view_layer.objects.active = o
        o.select_set(True)
        bpy.ops.object.convert(target='MESH')
        converted.append(name)
    except Exception as e:
        print("convert fail", name, e)
    try: o.select_set(False)
    except: pass
    bpy.ops.object.select_all(action='DESELECT')
tapers = [o.name for o in bpy.data.objects if o.name.endswith("_taper")]
for name in tapers:
    o = bpy.data.objects.get(name)
    if o: bpy.data.objects.remove(o, do_unlink=True)
bpy.ops.export_scene.gltf(filepath="//output/octopus-ramen-shop.glb", export_format='GLB')
result={"converted":converted, "removed_tapers":tapers}

