    if o is None:
        info[n]="MISSING"; continue
    mats=[]
    try: mats=[m.name if m else None for m in o.data.materials]
    except: pass
    vc=len(o.data.vertices) if o.type=='MESH' else -1
    info[n]={"type":o.type,"mats":mats,"verts":vc}
result=info

